import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture } from 'three/tsl';

export default async function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry matching atlas region aspect ratio (512x320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1, 1, 1);

  // Load the ceramic grain texture
  const texMap = await ctx.textureLoader.loadTexture(config.imageUrl);
  texMap.colorSpace = THREE.SRGBColorSpace;

  // Calculate UV offset for atlas region (0, 0, 512, 320)
  // Assuming full atlas is 512x512, region starts at (0,0) and is 512x320
  const uvNode = uv();
  const atlasUvNode = uvNode.mul(new THREE.Vector2(1, 320 / 512)).add(new THREE.Vector2(0, 0));

  // Create material using TSL nodes
  const material = new MeshBasicNodeMaterial({
    colorNode: texture(texMap, atlasUvNode),
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.copy(new THREE.Vector3(0, -0.3, 0));

  // Create cleanup handler
  const cleanup = () => {
    geometry.dispose();
    material.dispose();
    texMap.dispose();
  };

  // Attach handlers
  mesh.userData.handlers = {};
  mesh.userData.cleanup = cleanup;

  return mesh;
}
